export default function collectPeople({ persons, nextCursor, previousState }) {
  const state = previousState ?? { records: [], seen: [] };
  if (!Array.isArray(persons) || !Array.isArray(state.records) || !Array.isArray(state.seen))
    throw Error("Invalid Pipedrive page");
  const cursor = nextCursor ?? null;
  if (cursor !== null && (typeof cursor !== "string" || !cursor || state.seen.includes(cursor)))
    throw Error("Invalid or repeated Pipedrive cursor");
  return {
    state: {
      records: [...state.records, ...persons],
      seen: cursor ? [...state.seen, cursor] : state.seen,
    },
    more: cursor !== null,
    cursor: cursor ?? "unused",
  };
}

