export default function collectContacts({ results, paging, previousState }) {
  const state = previousState ?? { records: [], seen: [] };
  if (!Array.isArray(results) || !Array.isArray(state.records) || !Array.isArray(state.seen))
    throw Error("Invalid HubSpot page");
  const cursor = paging?.nextAfter ?? null;
  if (cursor !== null && (typeof cursor !== "string" || !cursor || state.seen.includes(cursor)))
    throw Error("Invalid or repeated HubSpot cursor");
  const records = [...state.records, ...results];
  if (records.length >= 10000) throw Error("HubSpot search limit reached; no contacts created");
  return {
    state: { records, seen: cursor ? [...state.seen, cursor] : state.seen },
    more: cursor !== null,
    cursor: cursor ?? "unused",
  };
}

