export default function planContacts({ people, contacts }) {
  if (!Array.isArray(people?.records) || !Array.isArray(contacts?.records))
    throw Error("Invalid contact lists");
  const present = new Set();
  for (const c of contacts.records) {
    const email = c?.properties?.email;
    if (email != null && typeof email !== "string") throw Error("Invalid HubSpot email");
    if (email) present.add(email.toLowerCase());
  }
  const proposed = [];
  for (const p of people.records) {
    const email = p?.emails?.[0]?.value;
    if (typeof email !== "string" || !email.trim() || email !== email.trim())
      throw Error("Pipedrive person has no usable first email");
    if (p.first_name != null && typeof p.first_name !== "string")
      throw Error("Invalid Pipedrive first name");
    const key = email.toLowerCase();
    if (!present.has(key)) {
      proposed.push({ email, ...(p.first_name ? { firstname: p.first_name } : {}) });
      present.add(key);
    }
  }
  return { contacts: proposed, hasContacts: proposed.length > 0 };
}

