export default function nextContact({ contacts, previousState }) {
  if (!Array.isArray(contacts)) throw Error("Invalid create list");
  const index = previousState?.index ?? 0;
  if (!Number.isInteger(index) || index < 0 || index > contacts.length)
    throw Error("Invalid position");
  return {
    state: { index: index + 1 },
    more: index < contacts.length,
    properties: contacts[index] ?? {},
  };
}
